import pandas as pd
import matplotlib.pyplot as plt
import sys

# --- Configuration ---
# The CSV file generated by your new bash script
CSV_FILE = "Results/RTX5000/mem_thru/unstructured_mem_thru.csv"
PLOT_OUTPUT_FILE = "Results/RTX5000/mem_thru/unstructured_mem_thru.png"
# --- End Configuration ---

def plot_throughput(csv_path, output_path):
    """
    Reads the throughput data and generates a log-log plot
    similar to Figure 6.6.
    """
    print(f"Reading data from {csv_path}...")
    try:
        # Read the CSV data
        data = pd.read_csv(csv_path)
    except FileNotFoundError:
        print(f"Error: CSV file not found at {csv_path}", file=sys.stderr)
        print("Please run the bash script first to generate the data.", file=sys.stderr)
        sys.exit(1)
    except pd.errors.EmptyDataError:
        print(f"Error: CSV file {csv_path} is empty.", file=sys.stderr)
        sys.exit(1)

    # Filter out any failed runs
    data = data[data['Throughput_GBps'] != 'FAIL'].copy()
    data['Throughput_GBps'] = pd.to_numeric(data['Throughput_GBps'])
    
    if data.empty:
        print("Error: No valid data to plot. All runs may have failed.", file=sys.stderr)
        sys.exit(1)

    print("Generating plot...")
    
    plt.figure(figsize=(10, 6))
    
    # Plot the main data
    plt.plot(
        data['Array_Size_MB'], 
        data['Throughput_GBps'], 
        marker='o',          # Add markers for data points
        linestyle='-',       # Connect markers with a line
        label='Measured Throughput'
    )
    
    # --- Set Logarithmic Scales ---
    # Set X-axis (Array Size) to log base 2
    # This makes 1, 2, 4, 8, 16... appear equidistant
    plt.xscale('log', base=2)
    
    # Set Y-axis (Throughput) to log base 10 (or base 2, both are common)
    # Figure 6.6 looks like log base 4 or log base 2, but we'll use base 2
    # for consistency with the x-axis.
    plt.yscale('log', base=2)

    # --- Formatting ---
    
    # Set x-axis ticks to match the array sizes
    # This makes the log-scale axis much cleaner to read
    x_ticks = data['Array_Size_MB'].unique()
    plt.xticks(x_ticks, labels=[str(xt) for xt in x_ticks])
    
    # Set y-axis ticks. You may need to adjust this based on your data range.
    # We can let matplotlib handle it automatically for log scale.
    from matplotlib.ticker import ScalarFormatter
    plt.gca().yaxis.set_major_formatter(ScalarFormatter())
    
    plt.title('Unstructured Memory Access Throughput vs. Array Size')
    plt.xlabel('Array Size (MB)')
    plt.ylabel('Peak Throughput (GB/s)')
    plt.grid(True, which='both', linestyle='--', linewidth=0.5)
    plt.legend()
    
    # Save the figure
    plt.savefig(output_path, dpi=300, bbox_inches='tight')
    
    print(f"Plot saved successfully to {output_path}")

if __name__ == "__main__":
    # Ensure the output directory exists
    import os
    os.makedirs(os.path.dirname(PLOT_OUTPUT_FILE), exist_ok=True)
    
    plot_throughput(CSV_FILE, PLOT_OUTPUT_FILE)